window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6f59793095653e00"]={"versions": [{"id": "FIG-6f59793095653e00", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelle Dokumentvorlage / Tabellenlayout (Requirements Table) im Rahmen des AUTOSAR-Standardisierungstemplates (TPS_StandardizationTemplate). Das Diagramm visualisiert das formale Dokumentationsmuster zur Spezifikation normativer Anforderungen (Software Specification Requirements, SWS) mit formaler Überschrift, Attributtabelle und abschließender Rückwärts-Traceability.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema besteht aus drei primären Bereichen:</p>\n<ul class=\"fig-list\"><li><strong>Kopfzeile:</strong> Formaler Anforderungsbezeichner <code>[SWS_FOO_07711]</code>, Titel <code>Formal Requirements shall look like this</code> sowie ein öffnendes Begrenzungszeichen <code>⌈</code>.\n</li><li><strong>Anforderungstabelle (Schlüssel-Wert-Paare):</strong>\n<ul class=\"fig-list\"><li><code>Type:</code> Anforderungstyp (Beispielwert: <code>valid</code>).\n</li><li><code>Description:</code> Optionale Detailbeschreibung zur Erläuterung; schließt eine normative Verfeinerung durch Schlüsselwörter aus.\n</li><li><code>Rationale:</code> Begründung der Notwendigkeit und Risiken bei Wegfall der Anforderung.\n</li><li><code>Use Case:</code> Anwendungsfälle, beispielhaft referenziert über IDs <code>[UC_FOO_00001]</code>, <code>[UC_FOO_00001]</code>.\n</li><li><code>Dependencies:</code> Abhängigkeiten zu anderen Anforderungen innerhalb des Dokuments (Semikolon-separiert), z. B. <code>[RS_TOC_00007]</code>, <code>[RS_TOC_00002]</code>.\n</li><li><code>Supporting Material:</code> Referenzen auf externe Dokumente, Modelle etc.\n</li></ul>\n</li><li><strong>Fußbereich / Traceability:</strong> Schließendes Begrenzungszeichen <code>⌋</code> gefolgt von einer Klammer mit Traceability-Verweisen auf übergeordnete Spezifikationen: <code>(SRS_FOO_00815, SRS_BAR_00007)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Darstellungs- und Metadatenmodell für Anforderungsdokumente ohne dynamische Verhaltenssequenz. Es definiert die visuelle Syntax und Struktur, wie Spezifikationswerkzeuge und Autoren Anforderungen bei der Dokumentengenerierung und -pflege erfassen und anordnen müssen. Die Umschließung durch <code>⌈</code> und <code>⌋</code> markiert den formal prüfbaren Gültigkeitsbereich der Anforderung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Syntax- und Formatvorgabe für AUTOSAR-Spezifikationen. Autoren und Modellierungswerkzeuge müssen jede Anforderung zwingend mit eindeutiger ID (<code>SWS_&lt;Modul&gt;_&lt;ID&gt;</code>), Titel, den typisierten Tabellenfeldern und den Traceability-Klammern ausstatten, um formale Konsistenzprüfungen, automatisiertes Parsing und vollständige Anforderungsverfolgung (SRS/RS-Traces) im Dokumenten-Buildprozess zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8390c12d5f44b222", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelle Dokumentvorlage / Tabellenlayout (Requirements Table) im Rahmen des AUTOSAR-Standardisierungstemplates (TPS_StandardizationTemplate). Das Diagramm visualisiert das formale Dokumentationsmuster zur Spezifikation normativer Anforderungen (Software Specification Requirements, SWS) mit formaler Überschrift, Attributtabelle und abschließender Rückwärts-Traceability.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema besteht aus drei primären Bereichen:</p>\n<ul class=\"fig-list\"><li><strong>Kopfzeile:</strong> Formaler Anforderungsbezeichner <code>[SWS_FOO_07711]</code>, Titel <code>Formal Requirements shall look like this</code> sowie ein öffnendes Begrenzungszeichen <code>⌈</code>.\n</li><li><strong>Anforderungstabelle (Schlüssel-Wert-Paare):</strong>\n<ul class=\"fig-list\"><li><code>Type:</code> Anforderungstyp (Beispielwert: <code>valid</code>).\n</li><li><code>Description:</code> Optionale Detailbeschreibung zur Erläuterung; schließt eine normative Verfeinerung durch Schlüsselwörter aus.\n</li><li><code>Rationale:</code> Begründung der Notwendigkeit und Risiken bei Wegfall der Anforderung.\n</li><li><code>Use Case:</code> Anwendungsfälle, beispielhaft referenziert über IDs <code>[UC_FOO_00001]</code>, <code>[UC_FOO_00001]</code>.\n</li><li><code>Dependencies:</code> Abhängigkeiten zu anderen Anforderungen innerhalb des Dokuments (Semikolon-separiert), z. B. <code>[RS_TOC_00007]</code>, <code>[RS_TOC_00002]</code>.\n</li><li><code>Supporting Material:</code> Referenzen auf externe Dokumente, Modelle etc.\n</li></ul>\n</li><li><strong>Fußbereich / Traceability:</strong> Schließendes Begrenzungszeichen <code>⌋</code> gefolgt von einer Klammer mit Traceability-Verweisen auf übergeordnete Spezifikationen: <code>(SRS_FOO_00815, SRS_BAR_00007)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Darstellungs- und Metadatenmodell für Anforderungsdokumente ohne dynamische Verhaltenssequenz. Es definiert die visuelle Syntax und Struktur, wie Spezifikationswerkzeuge und Autoren Anforderungen bei der Dokumentengenerierung und -pflege erfassen und anordnen müssen. Die Umschließung durch <code>⌈</code> und <code>⌋</code> markiert den formal prüfbaren Gültigkeitsbereich der Anforderung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Syntax- und Formatvorgabe für AUTOSAR-Spezifikationen. Autoren und Modellierungswerkzeuge müssen jede Anforderung zwingend mit eindeutiger ID (<code>SWS_&lt;Modul&gt;_&lt;ID&gt;</code>), Titel, den typisierten Tabellenfeldern und den Traceability-Klammern ausstatten, um formale Konsistenzprüfungen, automatisiertes Parsing und vollständige Anforderungsverfolgung (SRS/RS-Traces) im Dokumenten-Buildprozess zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-18b097e2c698b111", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelle Dokumentvorlage / Tabellenlayout (Requirements Table) im Rahmen des AUTOSAR-Standardisierungstemplates (TPS_StandardizationTemplate). Das Diagramm visualisiert das formale Dokumentationsmuster zur Spezifikation normativer Anforderungen (Software Specification Requirements, SWS) mit formaler Überschrift, Attributtabelle und abschließender Rückwärts-Traceability.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schema besteht aus drei primären Bereichen:</p>\n<ul class=\"fig-list\"><li><strong>Kopfzeile:</strong> Formaler Anforderungsbezeichner <code>[SWS_FOO_07711]</code>, Titel <code>Formal Requirements shall look like this</code> sowie ein öffnendes Begrenzungszeichen <code>⌈</code>.\n</li><li><strong>Anforderungstabelle (Schlüssel-Wert-Paare):</strong>\n<ul class=\"fig-list\"><li><code>Type:</code> Anforderungstyp (Beispielwert: <code>valid</code>).\n</li><li><code>Description:</code> Optionale Detailbeschreibung zur Erläuterung (<code>description</code>); schließt eine normative Verfeinerung durch Schlüsselwörter aus.\n</li><li><code>Rationale:</code> Begründung der Notwendigkeit und Risiken bei Wegfall der Anforderung im fortlaufenden Fließtext.\n</li><li><code>Use Case:</code> Anwendungsfälle mit differenzierten IDs <code>[UC_FOO_00001]</code>, <code>[UC_FOO_00002]</code>.\n</li><li><code>Applies to:</code> Plattform-Geltungsbereich mit Kennzeichnungen für Plattformen/Standards, beispielhaft <code>CP, TC</code>.\n</li><li><code>Dependencies:</code> Abhängigkeiten zu anderen Anforderungen innerhalb des Dokuments (Semikolon-separiert), z. B. <code>[RS_TOC_00007]</code>, <code>[RS_TOC_00002]</code>.\n</li><li><code>Supporting Material:</code> Referenzen auf externe Dokumente, Modelle etc.\n</li></ul>\n</li><li><strong>Fußbereich / Traceability:</strong> Schließendes Begrenzungszeichen <code>⌋</code> gefolgt von einer Klammer mit Traceability-Verweisen auf übergeordnete Spezifikationen: <code>(SRS_FOO_00815, SRS_BAR_00007)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Darstellungs- und Metadatenmodell für Anforderungsdokumente ohne dynamische Verhaltenssequenz. Es definiert die visuelle Syntax und Struktur, wie Spezifikationswerkzeuge und Autoren Anforderungen bei der Dokumentengenerierung und -pflege erfassen und anordnen müssen. Die Umschließung durch <code>⌈</code> und <code>⌋</code> markiert den formal prüfbaren Gültigkeitsbereich der Anforderung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Syntax- und Formatvorgabe für AUTOSAR-Spezifikationen. Autoren und Modellierungswerkzeuge müssen jede Anforderung zwingend mit eindeutiger ID (<code>SWS_&lt;Modul&gt;_&lt;ID&gt;</code>), Titel, den typisierten Tabellenfeldern einschließlich Plattform-Zuordnung (<code>Applies to:</code>) und Traceability-Klammern ausstatten, um formale Konsistenzprüfungen, plattformspezifisches Filtern (z. B. Classic Platform vs. weitere Standards) und vollständige Anforderungsverfolgung im Buildprozess sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6f59793095653e00", "to": "FIG-8390c12d5f44b222", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8390c12d5f44b222", "to": "FIG-18b097e2c698b111", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neue Tabellenzeile <code>Applies to:</code> mit dem Wert <code>CP, TC</code> eingefügt (Geltungsbereich für Classic Platform und Foundation/Template/Transforming Criteria).\n</li><li>Feld <code>Description:</code>: Tippfehlerkorrektur von „decription“ zu „description“.\n</li><li>Feld <code>Rationale:</code>: Zeilenumbruch und Einrückung neu gesetzt („Why is this requirement important, what its omission could cause? We deliberately should harmonize...“).\n</li><li>Feld <code>Use Case:</code>: Korrektur des zweiten Bezeichners von <code>[UC_FOO_00001]</code> auf <code>[UC_FOO_00002]</code>.\n</li></ul>"}]};
